/* Cross-platform hint to yield the CPU inside lock-free spin loops. */
#ifdef _WIN32
#include <windows.h>
static inline void js_thread_yield(void) { Sleep(0); }
#else
#include <sched.h>
static inline void js_thread_yield(void) { sched_yield(); }
#endif

