/* ============================================================================
 * GC Accessor Function Definitions
 * These functions are declared in quickjs.h but defined here where the
 * struct definitions are visible.
 * ============================================================================ */

/* JSObject shape_handle access */
GCHandle gc_obj_get_shape_handle(GCHandle obj_handle) {
    JSObjectHandle obj = obj_handle;
    if (SAFE_VALID(obj)) {
        return js_obj_shape_handle(obj);
    }
    return GC_HANDLE_NULL;
}

void gc_obj_set_shape_handle(GCHandle obj_handle, GCHandle val) {
    JSObjectHandle obj = obj_handle;
    if (SAFE_VALID(obj)) {
        js_obj_set_shape_handle(obj, val);
    }
}

/* JSObject prop_handle access */
GCHandle gc_obj_get_prop_handle(GCHandle obj_handle) {
    JSObjectHandle obj = obj_handle;
    if (SAFE_VALID(obj)) {
        return js_obj_prop_handle(obj);
    }
    return GC_HANDLE_NULL;
}

void gc_obj_set_prop_handle(GCHandle obj_handle, GCHandle val) {
    JSObjectHandle obj = obj_handle;
    if (SAFE_VALID(obj)) {
        js_obj_set_prop_handle(obj, val);
    }
}

/* JSShape proto_handle access */
GCHandle gc_shape_get_proto_handle(GCHandle shape_handle) {
    JSShapeHandle sh = shape_handle;
    if (SAFE_VALID(sh)) {
        return js_shape_proto_handle_atomic_load(sh);
    }
    return GC_HANDLE_NULL;
}

void gc_shape_set_proto_handle(GCHandle shape_handle, GCHandle val) {
    JSShapeHandle sh = shape_handle;
    if (SAFE_VALID(sh)) {
        js_shape_proto_handle_atomic_store(sh, val);
    }
}

/* js_object_get_proto_handle_atomic, find_own_property, js_get_field_fast:
 * shared with the JIT's stencils. */
#include "quickjs_props_inline.h"

JSShapeProperty *find_own_property_lost(JSProperty **ppr, JSObject *o, JSShape *s, JSShapeHandle sh,
                                        JSAtom atom)
{
    JSShapeProperty *prop = s->prop;
    for (int li = 0; li < s->prop_count; li++) {
        if (prop[li].atom == atom) {
            fprintf(stderr, "[FOP-LOST] atom %u at index %d of %d is not on its hash chain (shape %u)\n",
                    (unsigned)atom, li, s->prop_count, (unsigned)sh);
            fflush(stderr);
            *ppr = &js_obj_props_of(o)[li];
            return &prop[li];
        }
    }
    *ppr = NULL;
    return NULL;
}

/* JSObject boolean checks */
int gc_obj_is_exotic(GCHandle obj_handle) {
    JSObjectHandle obj = obj_handle;
    if (SAFE_VALID(obj)) {
        return SAFE_GET_OR(obj, JSObjectHandle, is_exotic, false) ? 1 : 0;
    }
    return 0;
}

int gc_obj_is_fast_array(GCHandle obj_handle) {
    JSObjectHandle obj = obj_handle;
    if (SAFE_VALID(obj)) {
        return SAFE_GET_OR(obj, JSObjectHandle, fast_array, false) ? 1 : 0;
    }
    return 0;
}

int gc_obj_is_extensible(GCHandle obj_handle) {
    JSObjectHandle obj = obj_handle;
    if (SAFE_VALID(obj)) {
        return SAFE_GET_OR(obj, JSObjectHandle, extensible, false) ? 1 : 0;
    }
    return 0;
}

