/* Element of a GC-heap array of GCHandle values (GC_HANDLE_NULL if the array
 * handle is NULL). */
static inline GCHandle gc_handle_array_get(GCHandle arr, int index)
{
    GCHandle *p = (GCHandle *)gc_deref(arr);
    return p ? p[index] : GC_HANDLE_NULL;
}

