#define GET_FIELD_INLINE(name, keep, is_length)                         \
            {                                                           \
                GCValue val = GC_UNDEFINED, obj = GC_UNDEFINED;         \
                JSAtom atom;                                            \
                JSObjectHandle p = GC_HANDLE_NULL;                           \
                JSProperty *pr;                                         \
                JSShapeProperty *prs;                                   \
