static GCValue js_string_charCodeAt(JSContextHandle ctx, GCValue this_val,
                                     int argc, GCValue *argv)
{
    GCValue val = GC_UNDEFINED, ret = GC_UNDEFINED;
    JSStringHandle p = GC_HANDLE_NULL;
    int idx, c;

    val = JS_ToStringCheckObject(ctx, this_val);
    if (JS_IsException(val))
        return val;
    p = JS_VALUE_GET_STRING(val);
    if (JS_ToInt32Sat(ctx, &idx, argv[0])) {
        
        return JS_EXCEPTION;
    }
    if (idx < 0 || idx >= SAFE_GET_OR(p, JSStringHandle, len, 0)) {
        ret = JS_NAN;
    } else {
        c = string_get(p, idx);
        ret = JS_NewInt32(ctx, c);
    }
    
    return ret;
}

static GCValue js_string_charAt(JSContextHandle ctx, GCValue this_val,
                                int argc, GCValue *argv, int is_at)
{
    GCValue val = GC_UNDEFINED, ret = GC_UNDEFINED;
    JSStringHandle p = GC_HANDLE_NULL;
    int idx, c;

    val = JS_ToStringCheckObject(ctx, this_val);
    if (JS_IsException(val))
        return val;
    p = JS_VALUE_GET_STRING(val);
    if (JS_ToInt32Sat(ctx, &idx, argv[0])) {
        
        return JS_EXCEPTION;
    }
    if (idx < 0 && is_at)
        idx += SAFE_GET_OR(p, JSStringHandle, len, 0);
    if (idx < 0 || idx >= SAFE_GET_OR(p, JSStringHandle, len, 0)) {
        if (is_at)
            ret = JS_UNDEFINED;
        else
            ret = JS_AtomToString(ctx, JS_ATOM_empty_string);
    } else {
        c = string_get(p, idx);
        ret = js_new_string_char(ctx, c);
    }
    
    return ret;
}

static GCValue js_string_codePointAt(JSContextHandle ctx, GCValue this_val,
                                     int argc, GCValue *argv)
{
    GCValue val = GC_UNDEFINED, ret = GC_UNDEFINED;
    JSStringHandle p = GC_HANDLE_NULL;
    int idx, c;

    val = JS_ToStringCheckObject(ctx, this_val);
    if (JS_IsException(val))
        return val;
    p = JS_VALUE_GET_STRING(val);
    if (JS_ToInt32Sat(ctx, &idx, argv[0])) {
        
        return JS_EXCEPTION;
    }
    if (idx < 0 || idx >= SAFE_GET_OR(p, JSStringHandle, len, 0)) {
        ret = JS_UNDEFINED;
    } else {
        c = string_getc(p, &idx);
        ret = JS_NewInt32(ctx, c);
    }
    
    return ret;
}

static GCValue js_string_concat(JSContextHandle ctx, GCValue this_val,
                                int argc, GCValue *argv)
{
    GCValue r = GC_UNDEFINED;
    int i;

    /* XXX: Use more efficient method */
    /* XXX: This method is OK if r has a single refcount */
    /* XXX: should use string_buffer? */
    r = JS_ToStringCheckObject(ctx, this_val);
    for (i = 0; i < argc; i++) {
        if (JS_IsException(r))
            break;
        r = JS_ConcatString(ctx, r, argv[i]);
    }
    return r;
}

static int string_cmp(JSStringHandle p1, JSStringHandle p2, int x1, int x2, int len)
{
    int i, c1, c2;
    for (i = 0; i < len; i++) {
        if ((c1 = string_get(p1, x1 + i)) != (c2 = string_get(p2, x2 + i)))
            return c1 - c2;
    }
    return 0;
}

static int string_indexof_char(JSStringHandle p, int c, int from)
{
    /* assuming 0 <= from <= p.len() */
    int i, len = SAFE_GET_OR(p, JSStringHandle, len, 0);
    if (SAFE_GET_OR(p, JSStringHandle, is_wide_char, 0)) {
        for (i = from; i < len; i++) {
            if (SAFE_GET_OR(p, JSStringHandle, u.str16, NULL)[i] == c)
                return i;
        }
    } else {
        if ((c & ~0xff) == 0) {
            for (i = from; i < len; i++) {
                if (SAFE_GET_OR(p, JSStringHandle, u.str8, NULL)[i] == (uint8_t)c)
                    return i;
            }
        }
    }
    return -1;
}

static int string_indexof(JSStringHandle p1, JSStringHandle p2, int from)
{
    /* assuming 0 <= from <= p1.len() */
    int c, i, j, len1 = SAFE_GET_OR(p1, JSStringHandle, len, 0), len2 = SAFE_GET_OR(p2, JSStringHandle, len, 0);
    if (len2 == 0)
        return from;
    for (i = from, c = string_get(p2, 0); i + len2 <= len1; i = j + 1) {
        j = string_indexof_char(p1, c, i);
        if (j < 0 || j + len2 > len1)
            break;
        if (!string_cmp(p1, p2, j + 1, 1, len2 - 1))
            return j;
    }
    return -1;
}

static int64_t string_advance_index(JSStringHandle p, int64_t index, BOOL unicode)
{
    if (!unicode || index >= SAFE_GET_OR(p, JSStringHandle, len, 0) || !SAFE_GET_OR(p, JSStringHandle, is_wide_char, 0)) {
        index++;
    } else {
        int index32 = (int)index;
        string_getc(p, &index32);
        index = index32;
    }
    return index;
}

/* return the position of the first invalid character in the string or
   -1 if none */
static int js_string_find_invalid_codepoint(JSStringHandle p)
{
    int i;
    if (!SAFE_GET_OR(p, JSStringHandle, is_wide_char, 0))
        return -1;
    for(i = 0; i < SAFE_GET_OR(p, JSStringHandle, len, 0); i++) {
        uint32_t c = SAFE_GET_OR(p, JSStringHandle, u.str16, NULL)[i];
        if (is_surrogate(c)) {
            if (is_hi_surrogate(c) && (i + 1) < SAFE_GET_OR(p, JSStringHandle, len, 0)
            &&  is_lo_surrogate(SAFE_GET_OR(p, JSStringHandle, u.str16, NULL)[i + 1])) {
                i++;
            } else {
                return i;
            }
        }
    }
    return -1;
}

static GCValue js_string_isWellFormed(JSContextHandle ctx, GCValue this_val,
                                      int argc, GCValue *argv)
{
    GCValue str = GC_UNDEFINED;
    JSStringHandle p = GC_HANDLE_NULL;
    BOOL ret;

    str = JS_ToStringCheckObject(ctx, this_val);
    if (JS_IsException(str))
        return JS_EXCEPTION;
    p = JS_VALUE_GET_STRING(str);
    ret = (js_string_find_invalid_codepoint(p) < 0);
    
    return JS_NewBool(ctx, ret);
}

static GCValue js_string_toWellFormed(JSContextHandle ctx, GCValue this_val,
                                      int argc, GCValue *argv)
{
    GCValue str = GC_UNDEFINED, ret = GC_UNDEFINED;
    JSStringHandle p = GC_HANDLE_NULL;
    int i;

    str = JS_ToStringCheckObject(ctx, this_val);
    if (JS_IsException(str))
        return JS_EXCEPTION;

    p = JS_VALUE_GET_STRING(str);
    /* avoid reallocating the string if it is well-formed */
    i = js_string_find_invalid_codepoint(p);
    if (i < 0)
        return str;

    ret = js_new_string16_len(ctx, SAFE_GET_OR(p, JSStringHandle, u.str16, NULL), SAFE_GET_OR(p, JSStringHandle, len, 0));
    
    if (JS_IsException(ret))
        return JS_EXCEPTION;

    p = JS_VALUE_GET_STRING(ret);
    for (; i < SAFE_GET_OR(p, JSStringHandle, len, 0); i++) {
        uint32_t c = SAFE_GET_OR(p, JSStringHandle, u.str16, NULL)[i];
        if (is_surrogate(c)) {
            if (is_hi_surrogate(c) && (i + 1) < SAFE_GET_OR(p, JSStringHandle, len, 0)
            &&  is_lo_surrogate(SAFE_GET_OR(p, JSStringHandle, u.str16, NULL)[i + 1])) {
                i++;
            } else {
                SAFE_GET_OR(p, JSStringHandle, u.str16, NULL)[i] = 0xFFFD;
            }
        }
    }
    return ret;
}

static GCValue js_string_indexOf(JSContextHandle ctx, GCValue this_val,
                                 int argc, GCValue *argv, int lastIndexOf)
{
    GCValue str = GC_UNDEFINED, v = GC_UNDEFINED;
    int i, len, v_len, pos, start, stop, ret, inc;
    JSStringHandle p = GC_HANDLE_NULL;
    JSStringHandle p1 = GC_HANDLE_NULL;

    str = JS_ToStringCheckObject(ctx, this_val);
    if (JS_IsException(str))
        return str;
    v = JS_ToString(ctx, argv[0]);
    if (JS_IsException(v))
        goto fail;
    p = JS_VALUE_GET_STRING(str);
    p1 = JS_VALUE_GET_STRING(v);
    len = SAFE_GET_OR(p, JSStringHandle, len, 0);
    v_len = SAFE_GET_OR(p1, JSStringHandle, len, 0);
    if (lastIndexOf) {
        pos = len - v_len;
        if (argc > 1) {
            double d;
            if (JS_ToFloat64(ctx, &d, argv[1]))
                goto fail;
            if (!isnan(d)) {
                if (d <= 0)
                    pos = 0;
                else if (d < pos)
                    pos = d;
            }
        }
        start = pos;
        stop = 0;
        inc = -1;
    } else {
        pos = 0;
        if (argc > 1) {
            if (JS_ToInt32Clamp(ctx, &pos, argv[1], 0, len, 0))
                goto fail;
        }
        start = pos;
        stop = len - v_len;
        inc = 1;
    }
    ret = -1;
    if (len >= v_len && inc * (stop - start) >= 0) {
        for (i = start;; i += inc) {
            if (!string_cmp(p, p1, i, 0, v_len)) {
                ret = i;
                break;
            }
            if (i == stop)
                break;
        }
    }
    
    
    return JS_NewInt32(ctx, ret);

fail:
    
    
    return JS_EXCEPTION;
}

/* return < 0 if exception or TRUE/FALSE */
static int js_is_regexp(JSContextHandle ctx, GCValue obj);

static GCValue js_string_includes(JSContextHandle ctx, GCValue this_val,
                                  int argc, GCValue *argv, int magic)
{
    GCValue str = GC_UNDEFINED, v = JS_UNDEFINED;
    int i, len, v_len, pos, start, stop, ret;
    JSStringHandle p = GC_HANDLE_NULL;
    JSStringHandle p1 = GC_HANDLE_NULL;

    str = JS_ToStringCheckObject(ctx, this_val);
    if (JS_IsException(str))
        return str;
    ret = js_is_regexp(ctx, argv[0]);
    if (ret) {
        if (ret > 0)
            JS_ThrowTypeError(ctx, "regexp not supported");
        goto fail;
    }
    v = JS_ToString(ctx, argv[0]);
    if (JS_IsException(v))
        goto fail;
    p = JS_VALUE_GET_STRING(str);
    p1 = JS_VALUE_GET_STRING(v);
    len = SAFE_GET_OR(p, JSStringHandle, len, 0);
    v_len = SAFE_GET_OR(p1, JSStringHandle, len, 0);
    pos = (magic == 2) ? len : 0;
    if (argc > 1 && !JS_IsUndefined(argv[1])) {
        if (JS_ToInt32Clamp(ctx, &pos, argv[1], 0, len, 0))
            goto fail;
    }
    len -= v_len;
    ret = 0;
    if (magic == 0) {
        start = pos;
        stop = len;
    } else {
        if (magic == 1) {
            if (pos > len)
                goto done;
        } else {
            pos -= v_len;
        }
        start = stop = pos;
    }
    if (start >= 0 && start <= stop) {
        for (i = start;; i++) {
            if (!string_cmp(p, p1, i, 0, v_len)) {
                ret = 1;
                break;
            }
            if (i == stop)
                break;
        }
    }
 done:
    
    
    return JS_NewBool(ctx, ret);

fail:
    
    
    return JS_EXCEPTION;
}

static int check_regexp_g_flag(JSContextHandle ctx, GCValue regexp)
{
    int ret;
    GCValue flags = GC_UNDEFINED;

    ret = js_is_regexp(ctx, regexp);
    if (ret < 0)
        return -1;
    if (ret) {
        flags = JS_GetProperty(ctx, regexp, JS_ATOM_flags);
        if (JS_IsException(flags))
            return -1;
        if (JS_IsUndefined(flags) || JS_IsNull(flags)) {
            JS_ThrowTypeError(ctx, "cannot convert to object");
            return -1;
        }
        flags = JS_ToStringFree(ctx, flags);
        if (JS_IsException(flags))
            return -1;
        ret = string_indexof_char(JS_VALUE_GET_STRING(flags), 'g', 0);
        
        if (ret < 0) {
            JS_ThrowTypeError(ctx, "regexp must have the 'g' flag");
            return -1;
        }
    }
    return 0;
}

static GCValue js_string_match(JSContextHandle ctx, GCValue this_val,
                               int argc, GCValue *argv, int atom)
{
    // match(rx), search(rx), matchAll(rx)
    // atom is JS_ATOM_Symbol_match, JS_ATOM_Symbol_search, or JS_ATOM_Symbol_matchAll
    GCValue O = this_val, regexp = argv[0], args[2] = { [0 ... (2) - 1] = GC_UNDEFINED_INIT };
    GCValue matcher = GC_UNDEFINED, S = GC_UNDEFINED, rx = GC_UNDEFINED, result = GC_UNDEFINED, str = GC_UNDEFINED;
    int args_len;

    if (JS_IsUndefined(O) || JS_IsNull(O))
        return JS_ThrowTypeError(ctx, "cannot convert to object");

    if (JS_IsObject(regexp)) {
        matcher = JS_GetProperty(ctx, regexp, atom);
        if (JS_IsException(matcher))
            return JS_EXCEPTION;
        if (atom == JS_ATOM_Symbol_matchAll) {
            if (check_regexp_g_flag(ctx, regexp) < 0) {
                
                return JS_EXCEPTION;
            }
        }
        if (!JS_IsUndefined(matcher) && !JS_IsNull(matcher)) {
            return JS_CallFree(ctx, matcher, regexp, 1, &O);
        }
    }
    S = JS_ToString(ctx, O);
    if (JS_IsException(S))
        return JS_EXCEPTION;
    args_len = 1;
    args[0] = regexp;
    str = JS_UNDEFINED;
    if (atom == JS_ATOM_Symbol_matchAll) {
        str = js_new_string8(ctx, "g");
        if (JS_IsException(str))
            goto fail;
        args[args_len++] = (GCValue)str;
    }
    rx = JS_CallConstructor(ctx, SAFE_GET_OR(ctx, JSContextHandle, regexp_ctor, GC_UNDEFINED), args_len, args);
    
    if (JS_IsException(rx)) {
    fail:
        
        return JS_EXCEPTION;
    }
    result = JS_InvokeFree(ctx, rx, atom, 1, (GCValue *)&S);
    
    return result;
}

/* if captures != NULL, captures_val and matched are ignored. Otherwise,
   captures_len is ignored */
static int js_string_GetSubstitution(JSContextHandle ctx,
                                     StringBuffer *b,
                                     GCValue matched,
                                     JSStringHandle sp,
                                     uint32_t position,
                                     GCValue captures_val,
                                     GCValue namedCaptures,
                                     GCValue rep,
                                     uint8_t **captures,
                                     uint32_t captures_len)
{
    GCValue capture = GC_UNDEFINED, name = GC_UNDEFINED, s = GC_UNDEFINED;
    uint32_t len, matched_len;
    int i, j, j0, k, k1, shift;
    int c, c1;
    JSStringHandle rp = GC_HANDLE_NULL;

    if (JS_VALUE_GET_TAG(rep) != JS_TAG_STRING) {
        JS_ThrowTypeError(ctx, "not a string");
        goto exception;
    }
    shift = SAFE_GET_OR(sp, JSStringHandle, is_wide_char, 0);
    rp = JS_VALUE_GET_STRING(rep);

    if (captures) {
        matched_len = (captures[1] - captures[0]) >> shift;
    } else {
        captures_len = 0;
        if (!JS_IsUndefined(captures_val)) {
            if (js_get_length32(ctx, &captures_len, captures_val))
                goto exception;
        }
        if (js_get_length32(ctx, &matched_len, matched))
            goto exception;
    }

    len = SAFE_GET_OR(rp, JSStringHandle, len, 0);
    i = 0;
    for(;;) {
        j = string_indexof_char(rp, '$', i);
        if (j < 0 || j + 1 >= len)
            break;
        string_buffer_concat(b, rp, i, j);
        j0 = j++;
        c = string_get(rp, j++);
        if (c == '$') {
            string_buffer_putc8(b, '$');
        } else if (c == '&') {
            if (captures) {
                string_buffer_concat(b, sp, position, position + matched_len);
            } else {
                if (string_buffer_concat_value(b, matched))
                    goto exception;
            }
        } else if (c == '`') {
            string_buffer_concat(b, sp, 0, position);
        } else if (c == '\'') {
            string_buffer_concat(b, sp, position + matched_len, SAFE_GET_OR(sp, JSStringHandle, len, 0));
        } else if (c >= '0' && c <= '9') {
            k = c - '0';
            if (j < len) {
                c1 = string_get(rp, j);
                if (c1 >= '0' && c1 <= '9') {
                    /* This behavior is specified in ES6 and refined in ECMA 2019 */
                    /* ECMA 2019 does not have the extra test, but
                       Test262 S15.5.4.11_A3_T1..3 require this behavior */
                    k1 = k * 10 + c1 - '0';
                    if (k1 >= 1 && k1 < captures_len) {
                        k = k1;
                        j++;
                    }
                }
            }
            if (k >= 1 && k < captures_len) {
                if (captures) {
                    int start, end;
                    if (captures[2 * k] && captures[2 * k + 1]) {
                        start = (captures[2 * k] - SAFE_GET_OR(sp, JSStringHandle, u.str8, NULL)) >> shift;
                        end = (captures[2 * k + 1] - SAFE_GET_OR(sp, JSStringHandle, u.str8, NULL)) >> shift;
                        string_buffer_concat(b, sp, start, end);
                    }
                } else {
                    s = JS_GetPropertyInt64(ctx, captures_val, k);
                    if (JS_IsException(s))
                        goto exception;
                    if (!JS_IsUndefined(s)) {
                        if (string_buffer_concat_value_free(b, s))
                            goto exception;
                    }
                }
            } else {
                goto norep;
            }
        } else if (c == '<' && !JS_IsUndefined(namedCaptures)) {
            k = string_indexof_char(rp, '>', j);
            if (k < 0)
                goto norep;
            name = js_sub_string(ctx, rp, j, k);
            if (JS_IsException(name))
                goto exception;
            capture = JS_GetPropertyValue(ctx, namedCaptures, name);
            if (JS_IsException(capture))
                goto exception;
            if (!JS_IsUndefined(capture)) {
                if (string_buffer_concat_value_free(b, capture))
                    goto exception;
            }
            j = k + 1;
        } else {
        norep:
            string_buffer_concat(b, rp, j0, j);
        }
        i = j;
    }
    string_buffer_concat(b, rp, i, SAFE_GET_OR(rp, JSStringHandle, len, 0));
    return 0;
exception:
    return -1;
}

static GCValue js_string_replace(JSContextHandle ctx, GCValue this_val,
                                 int argc, GCValue *argv,
                                 int is_replaceAll)
{
    // replace(rx, rep)
    GCValue O = this_val, searchValue = argv[0], replaceValue = argv[1];
    GCValue args[3] = { [0 ... (3) - 1] = GC_UNDEFINED_INIT };
    GCValue str = GC_UNDEFINED, search_str = GC_UNDEFINED, replaceValue_str = GC_UNDEFINED, repl_str = GC_UNDEFINED;
    JSStringHandle sp = GC_HANDLE_NULL, searchp = GC_HANDLE_NULL;
    StringBuffer b_s, *b = &b_s;
    int pos, functionalReplace, endOfLastMatch;
    BOOL is_first;

    if (JS_IsUndefined(O) || JS_IsNull(O))
        return JS_ThrowTypeError(ctx, "cannot convert to object");

    search_str = JS_UNDEFINED;
    replaceValue_str = JS_UNDEFINED;
    repl_str = JS_UNDEFINED;

    if (JS_IsObject(searchValue)) {
        GCValue replacer = GC_UNDEFINED;
        if (is_replaceAll) {
            if (check_regexp_g_flag(ctx, searchValue) < 0)
                return JS_EXCEPTION;
        }
        replacer = JS_GetProperty(ctx, searchValue, JS_ATOM_Symbol_replace);
        if (JS_IsException(replacer))
            return JS_EXCEPTION;
        if (!JS_IsUndefined(replacer) && !JS_IsNull(replacer)) {
            args[0] = O;
            args[1] = replaceValue;
            return JS_CallFree(ctx, replacer, searchValue, 2, args);
        }
    }
    string_buffer_init(ctx, b, 0);

    str = JS_ToString(ctx, O);
    if (JS_IsException(str))
        goto exception;
    search_str = JS_ToString(ctx, searchValue);
    if (JS_IsException(search_str))
        goto exception;
    functionalReplace = JS_IsFunction(ctx, replaceValue);
    if (!functionalReplace) {
        replaceValue_str = JS_ToString(ctx, replaceValue);
        if (JS_IsException(replaceValue_str))
            goto exception;
    }

    sp = JS_VALUE_GET_STRING(str);
    searchp = JS_VALUE_GET_STRING(search_str);
    endOfLastMatch = 0;
    is_first = TRUE;
    for(;;) {
        if (unlikely(SAFE_GET_OR(searchp, JSStringHandle, len, 0) == 0)) {
            if (is_first)
                pos = 0;
            else if (endOfLastMatch >= SAFE_GET_OR(sp, JSStringHandle, len, 0))
                pos = -1;
            else
                pos = endOfLastMatch + 1;
        } else {
            pos = string_indexof(sp, searchp, endOfLastMatch);
        }
        if (pos < 0) {
            if (is_first) {
                string_buffer_free(b);
                
                
                return str;
            } else {
                break;
            }
        }

        string_buffer_concat(b, sp, endOfLastMatch, pos);

        if (functionalReplace) {
            args[0] = search_str;
            args[1] = JS_NewInt32(ctx, pos);
            args[2] = str;
            repl_str = JS_ToStringFree(ctx, JS_Call(ctx, replaceValue, JS_UNDEFINED, 3, args));
            if (JS_IsException(repl_str))
                goto exception;
            string_buffer_concat_value_free(b, repl_str);
        } else {
            if (js_string_GetSubstitution(ctx, b, search_str, sp, pos,
                                          JS_UNDEFINED, JS_UNDEFINED, replaceValue_str,
                                          NULL, 0)) {
                goto exception;
            }
        }

        endOfLastMatch = pos + SAFE_GET_OR(searchp, JSStringHandle, len, 0);
        is_first = FALSE;
        if (!is_replaceAll)
            break;
    }
    string_buffer_concat(b, sp, endOfLastMatch, SAFE_GET_OR(sp, JSStringHandle, len, 0));
    
    
    
    return string_buffer_end(b);

exception:
    string_buffer_free(b);
    
    
    
    return JS_EXCEPTION;
}

static GCValue js_string_split(JSContextHandle ctx, GCValue this_val,
                               int argc, GCValue *argv)
{
    // split(sep, limit)
    GCValue O = this_val, separator = argv[0], limit = argv[1];
    GCValue args[2] = { [0 ... (2) - 1] = GC_UNDEFINED_INIT };
    GCValue S = GC_UNDEFINED, A = GC_UNDEFINED, R = GC_UNDEFINED, T = GC_UNDEFINED;
    uint32_t lim, lengthA;
    int64_t p, q, s, r, e;
    JSStringHandle sp = GC_HANDLE_NULL, rp = GC_HANDLE_NULL;

    if (JS_IsUndefined(O) || JS_IsNull(O))
        return JS_ThrowTypeError(ctx, "cannot convert to object");

    S = JS_UNDEFINED;
    A = JS_UNDEFINED;
    R = JS_UNDEFINED;

    if (JS_IsObject(separator)) {
        GCValue splitter = GC_UNDEFINED;
        splitter = JS_GetProperty(ctx, separator, JS_ATOM_Symbol_split);
        if (JS_IsException(splitter))
            return JS_EXCEPTION;
        if (!JS_IsUndefined(splitter) && !JS_IsNull(splitter)) {
            args[0] = O;
            args[1] = limit;
            return JS_CallFree(ctx, splitter, separator, 2, args);
        }
    }
    S = JS_ToString(ctx, O);
    if (JS_IsException(S))
        goto exception;
    A = JS_NewArray(ctx);
    if (JS_IsException(A))
        goto exception;
    lengthA = 0;
    if (JS_IsUndefined(limit)) {
        lim = 0xffffffff;
    } else {
        if (JS_ToUint32(ctx, &lim, limit) < 0)
            goto exception;
    }
    sp = JS_VALUE_GET_STRING(S);
    s = SAFE_GET_OR(sp, JSStringHandle, len, 0);
    R = JS_ToString(ctx, separator);
    if (JS_IsException(R))
        goto exception;
    rp = JS_VALUE_GET_STRING(R);
    r = SAFE_GET_OR(rp, JSStringHandle, len, 0);
    p = 0;
    if (lim == 0)
        goto done;
    if (JS_IsUndefined(separator))
        goto add_tail;
    if (s == 0) {
        if (r != 0)
            goto add_tail;
        goto done;
    }
    for (q = p; (q += !r) <= s - r - !r; q = p = e + r) {
        e = string_indexof(sp, rp, q);
        if (e < 0)
            break;
        T = js_sub_string(ctx, sp, p, e);
        if (JS_IsException(T))
            goto exception;
        if (JS_CreateDataPropertyUint32(ctx, A, lengthA++, T, 0) < 0)
            goto exception;
        if (lengthA == lim)
            goto done;
    }
add_tail:
    T = js_sub_string(ctx, sp, p, s);
    if (JS_IsException(T))
        goto exception;
    if (JS_CreateDataPropertyUint32(ctx, A, lengthA++, T,0 ) < 0)
        goto exception;
done:
    
    
    return A;

exception:
    
    
    
    return JS_EXCEPTION;
}

static GCValue js_string_substring(JSContextHandle ctx, GCValue this_val,
                                   int argc, GCValue *argv)
{
    GCValue str = GC_UNDEFINED, ret = GC_UNDEFINED;
    int a, b, start, end;
    JSStringHandle p = GC_HANDLE_NULL;

    str = JS_ToStringCheckObject(ctx, this_val);
    if (JS_IsException(str))
        return str;
    p = JS_VALUE_GET_STRING(str);
    if (JS_ToInt32Clamp(ctx, &a, argv[0], 0, SAFE_GET_OR(p, JSStringHandle, len, 0), 0)) {
        
        return JS_EXCEPTION;
    }
    b = SAFE_GET_OR(p, JSStringHandle, len, 0);
    if (!JS_IsUndefined(argv[1])) {
        if (JS_ToInt32Clamp(ctx, &b, argv[1], 0, SAFE_GET_OR(p, JSStringHandle, len, 0), 0)) {
            
            return JS_EXCEPTION;
        }
    }
    if (a < b) {
        start = a;
        end = b;
    } else {
        start = b;
        end = a;
    }
    ret = js_sub_string(ctx, p, start, end);
    
    return ret;
}

static GCValue js_string_substr(JSContextHandle ctx, GCValue this_val,
                                int argc, GCValue *argv)
{
    GCValue str = GC_UNDEFINED, ret = GC_UNDEFINED;
    int a, len, n;
    JSStringHandle p = GC_HANDLE_NULL;

    str = JS_ToStringCheckObject(ctx, this_val);
    if (JS_IsException(str))
        return str;
    p = JS_VALUE_GET_STRING(str);
    len = SAFE_GET_OR(p, JSStringHandle, len, 0);
    if (JS_ToInt32Clamp(ctx, &a, argv[0], 0, len, len)) {
        
        return JS_EXCEPTION;
    }
    n = len - a;
    if (!JS_IsUndefined(argv[1])) {
        if (JS_ToInt32Clamp(ctx, &n, argv[1], 0, len - a, 0)) {
            
            return JS_EXCEPTION;
        }
    }
    ret = js_sub_string(ctx, p, a, a + n);
    
    return ret;
}

static GCValue js_string_slice(JSContextHandle ctx, GCValue this_val,
                               int argc, GCValue *argv)
{
    GCValue str = GC_UNDEFINED, ret = GC_UNDEFINED;
    int len, start, end;
    JSStringHandle p = GC_HANDLE_NULL;

    str = JS_ToStringCheckObject(ctx, this_val);
    if (JS_IsException(str))
        return str;
    p = JS_VALUE_GET_STRING(str);
    len = SAFE_GET_OR(p, JSStringHandle, len, 0);
    if (JS_ToInt32Clamp(ctx, &start, argv[0], 0, len, len)) {
        
        return JS_EXCEPTION;
    }
    end = len;
    if (!JS_IsUndefined(argv[1])) {
        if (JS_ToInt32Clamp(ctx, &end, argv[1], 0, len, len)) {
            
            return JS_EXCEPTION;
        }
    }
    ret = js_sub_string(ctx, p, start, max_int(end, start));
    
    return ret;
}

static GCValue js_string_pad(JSContextHandle ctx, GCValue this_val,
                             int argc, GCValue *argv, int padEnd)
{
    GCValue str = GC_UNDEFINED, v = JS_UNDEFINED;
    StringBuffer b_s, *b = &b_s;
    JSStringHandle p = GC_HANDLE_NULL, p1 = GC_HANDLE_NULL;
    int n, len, c = ' ';

    str = JS_ToStringCheckObject(ctx, this_val);
    if (JS_IsException(str))
        goto fail1;
    if (JS_ToInt32Sat(ctx, &n, argv[0]))
        goto fail2;
    p = JS_VALUE_GET_STRING(str);
    len = SAFE_GET_OR(p, JSStringHandle, len, 0);
    if (len >= n)
        return str;
    if (argc > 1 && !JS_IsUndefined(argv[1])) {
        v = JS_ToString(ctx, argv[1]);
        if (JS_IsException(v))
            goto fail2;
        p1 = JS_VALUE_GET_STRING(v);
        if (SAFE_GET_OR(p1, JSStringHandle, len, 0) == 0) {
            
            return str;
        }
        if (SAFE_GET_OR(p1, JSStringHandle, len, 0) == 1) {
            c = string_get(p1, 0);
            p1 = GC_HANDLE_NULL;
        }
    }
    if (n > JS_STRING_LEN_MAX) {
        JS_ThrowRangeError(ctx, "invalid string length");
        goto fail3;
    }
    if (string_buffer_init(ctx, b, n))
        goto fail3;
    n -= len;
    if (padEnd) {
        if (string_buffer_concat(b, p, 0, len))
            goto fail;
    }
    if (SAFE_VALID(p1)) {
        while (n > 0) {
            int chunk = min_int(n, SAFE_GET_OR(p1, JSStringHandle, len, 0));
            if (string_buffer_concat(b, p1, 0, chunk))
                goto fail;
            n -= chunk;
        }
    } else {
        if (string_buffer_fill(b, c, n))
            goto fail;
    }
    if (!padEnd) {
        if (string_buffer_concat(b, p, 0, len))
            goto fail;
    }
    
    
    return string_buffer_end(b);

fail:
    string_buffer_free(b);
fail3:
    
fail2:
    
fail1:
    return JS_EXCEPTION;
}

static GCValue js_string_repeat(JSContextHandle ctx, GCValue this_val,
                                int argc, GCValue *argv)
{
    GCValue str = GC_UNDEFINED;
    StringBuffer b_s, *b = &b_s;
    JSStringHandle p = GC_HANDLE_NULL;
    int64_t val;
    int n, len;

    str = JS_ToStringCheckObject(ctx, this_val);
    if (JS_IsException(str))
        goto fail;
    if (JS_ToInt64Sat(ctx, &val, argv[0]))
        goto fail;
    if (val < 0 || val > 2147483647) {
        JS_ThrowRangeError(ctx, "invalid repeat count");
        goto fail;
    }
    n = val;
    p = JS_VALUE_GET_STRING(str);
    len = SAFE_GET_OR(p, JSStringHandle, len, 0);
    if (len == 0 || n == 1)
        return str;
    // XXX: potential arithmetic overflow
    if (val * len > JS_STRING_LEN_MAX) {
        JS_ThrowRangeError(ctx, "invalid string length");
        goto fail;
    }
    if (string_buffer_init2(ctx, b, n * len, SAFE_GET_OR(p, JSStringHandle, is_wide_char, 0)))
        goto fail;
    if (len == 1) {
        string_buffer_fill(b, string_get(p, 0), n);
    } else {
        while (n-- > 0) {
            string_buffer_concat(b, p, 0, len);
        }
    }
    
    return string_buffer_end(b);

fail:
    
    return JS_EXCEPTION;
}

static GCValue js_string_trim(JSContextHandle ctx, GCValue this_val,
                              int argc, GCValue *argv, int magic)
{
    GCValue str = GC_UNDEFINED, ret = GC_UNDEFINED;
    int a, b, len;
    JSStringHandle p = GC_HANDLE_NULL;

    str = JS_ToStringCheckObject(ctx, this_val);
    if (JS_IsException(str))
        return str;
    p = JS_VALUE_GET_STRING(str);
    a = 0;
    b = len = SAFE_GET_OR(p, JSStringHandle, len, 0);
    if (magic & 1) {
        while (a < len && lre_is_space(string_get(p, a)))
            a++;
    }
    if (magic & 2) {
        while (b > a && lre_is_space(string_get(p, b - 1)))
            b--;
    }
    ret = js_sub_string(ctx, p, a, b);
    
    return ret;
}

/* return 0 if before the first char */
static int string_prevc(JSStringHandle p, int *pidx)
{
    int idx, c, c1;

    idx = *pidx;
    if (idx <= 0)
        return 0;
    idx--;
    if (SAFE_GET_OR(p, JSStringHandle, is_wide_char, 0)) {
        c = SAFE_GET_OR(p, JSStringHandle, u.str16, NULL)[idx];
        if (is_lo_surrogate(c) && idx > 0) {
            c1 = SAFE_GET_OR(p, JSStringHandle, u.str16, NULL)[idx - 1];
            if (is_hi_surrogate(c1)) {
                c = from_surrogate(c1, c);
                idx--;
            }
        }
    } else {
        c = SAFE_GET_OR(p, JSStringHandle, u.str8, NULL)[idx];
    }
    *pidx = idx;
    return c;
}

static BOOL test_final_sigma(JSStringHandle p, int sigma_pos)
{
    int k, c1;

    /* before C: skip case ignorable chars and check there is
       a cased letter */
    k = sigma_pos;
    for(;;) {
        c1 = string_prevc(p, &k);
        if (!lre_is_case_ignorable(c1))
            break;
    }
    if (!lre_is_cased(c1))
        return FALSE;

    /* after C: skip case ignorable chars and check there is
       no cased letter */
    k = sigma_pos + 1;
    for(;;) {
        if (k >= SAFE_GET_OR(p, JSStringHandle, len, 0))
            return TRUE;
        c1 = string_getc(p, &k);
        if (!lre_is_case_ignorable(c1))
            break;
    }
    return !lre_is_cased(c1);
}

static GCValue js_string_toLowerCase(JSContextHandle ctx, GCValue this_val,
                                     int argc, GCValue *argv, int to_lower)
{
    GCValue val = GC_UNDEFINED;
    StringBuffer b_s, *b = &b_s;
    JSStringHandle p = GC_HANDLE_NULL;
    int i, c, j, l;
    uint32_t res[LRE_CC_RES_LEN_MAX];

    val = JS_ToStringCheckObject(ctx, this_val);
    if (JS_IsException(val))
        return val;
    p = JS_VALUE_GET_STRING(val);
    if (SAFE_GET_OR(p, JSStringHandle, len, 0) == 0)
        return val;
    if (string_buffer_init(ctx, b, SAFE_GET_OR(p, JSStringHandle, len, 0)))
        goto fail;
    for(i = 0; i < SAFE_GET_OR(p, JSStringHandle, len, 0);) {
        c = string_getc(p, &i);
        if (c == 0x3a3 && to_lower && test_final_sigma(p, i - 1)) {
            res[0] = 0x3c2; /* final sigma */
            l = 1;
        } else {
            l = lre_case_conv(res, c, to_lower);
        }
        for(j = 0; j < l; j++) {
            if (string_buffer_putc(b, res[j]))
                goto fail;
        }
    }
    
    return string_buffer_end(b);
 fail:
    
    string_buffer_free(b);
    return JS_EXCEPTION;
}

#ifdef CONFIG_ALL_UNICODE

/* return (-1, NULL) if exception, otherwise (len, buf) */
static int JS_ToUTF32String(JSContextHandle ctx, uint32_t **pbuf, GCValue val1)
{
    GCValue val = GC_UNDEFINED;
    JSStringHandle p = GC_HANDLE_NULL;
    uint32_t *buf;
    int i, j, len;

    val = JS_ToString(ctx, val1);
    if (JS_IsException(val))
        return -1;
    p = JS_VALUE_GET_STRING(val);
    len = SAFE_GET_OR(p, JSStringHandle, len, 0);
    /* UTF32 buffer length is len minus the number of correct surrogates pairs */
    /* libc buffer: a short-lived temporary (unicode_normalize input),
     * released by the caller. */
    buf = (uint32_t *)unicode_libc_realloc(NULL, NULL, sizeof(buf[0]) * max_int(len, 1));
    if (!buf) {
        
        goto fail;
    }
    for(i = j = 0; i < len;)
        buf[j++] = string_getc(p, &i);
    
    *pbuf = buf;
    return j;
 fail:
    *pbuf = NULL;
    return -1;
}

static GCValue JS_NewUTF32String(JSContextHandle ctx, const uint32_t *buf, int len)
{
    int i;
    StringBuffer b_s, *b = &b_s;
    if (string_buffer_init(ctx, b, len))
        return JS_EXCEPTION;
    for(i = 0; i < len; i++) {
        if (string_buffer_putc(b, buf[i]))
            goto fail;
    }
    return string_buffer_end(b);
 fail:
    string_buffer_free(b);
    return JS_EXCEPTION;
}

static int js_string_normalize1(JSContextHandle ctx, uint32_t **pout_buf,
                                GCValue val,
                                UnicodeNormalizationEnum n_type)
{
    int buf_len, out_len;
    uint32_t *buf, *out_buf;

    buf_len = JS_ToUTF32String(ctx, &buf, val);
    if (buf_len < 0)
        return -1;
    /* libc allocator: unicode_normalize grows a DynBuf of raw pointers, which
     * the handle-based gc_realloc cannot back.  The caller releases out_buf
     * with unicode_libc_realloc(NULL, out_buf, 0). */
    out_len = unicode_normalize(&out_buf, buf, buf_len, n_type,
                                NULL, unicode_libc_realloc);
    unicode_libc_realloc(NULL, buf, 0);
    if (out_len < 0)
        return -1;
    *pout_buf = out_buf;
    return out_len;
}

static GCValue js_string_normalize(JSContextHandle ctx, GCValue this_val,
                                   int argc, GCValue *argv)
{
    const char *form, *p;
    size_t form_len;
    int is_compat, out_len;
    UnicodeNormalizationEnum n_type;
    GCValue val = GC_UNDEFINED;
    uint32_t *out_buf;

    val = JS_ToStringCheckObject(ctx, this_val);
    if (JS_IsException(val))
        return val;

    if (argc == 0 || JS_IsUndefined(argv[0])) {
        n_type = UNICODE_NFC;
    } else {
        form = JS_ToCStringLen(ctx, &form_len, argv[0]);
        if (!form)
            goto fail1;
        p = form;
        if (p[0] != 'N' || p[1] != 'F')
            goto bad_form;
        p += 2;
        is_compat = FALSE;
        if (*p == 'K') {
            is_compat = TRUE;
            p++;
        }
        if (*p == 'C' || *p == 'D') {
            n_type = (UnicodeNormalizationEnum)(UNICODE_NFC + is_compat * 2 + (*p - 'C'));
            if ((p + 1 - form) != form_len)
                goto bad_form;
        } else {
        bad_form:
            JS_ThrowRangeError(ctx, "bad normalization form");
        fail1:
            
            return JS_EXCEPTION;
        }
    }

    out_len = js_string_normalize1(ctx, &out_buf, val, n_type);
    
    if (out_len < 0)
        return JS_EXCEPTION;
    val = JS_NewUTF32String(ctx, out_buf, out_len);
    unicode_libc_realloc(NULL, out_buf, 0);
    return val;
}

/* return < 0, 0 or > 0 */
static int js_UTF32_compare(const uint32_t *buf1, int buf1_len,
                            const uint32_t *buf2, int buf2_len)
{
    int i, len, c, res;
    len = min_int(buf1_len, buf2_len);
    for(i = 0; i < len; i++) {
        /* Note: range is limited so a subtraction is valid */
        c = buf1[i] - buf2[i];
        if (c != 0)
            return c;
    }
    if (buf1_len == buf2_len)
        res = 0;
    else if (buf1_len < buf2_len)
        res = -1;
    else
        res = 1;
    return res;
}

static GCValue js_string_localeCompare(JSContextHandle ctx, GCValue this_val,
                                       int argc, GCValue *argv)
{
    GCValue a = GC_UNDEFINED, b = GC_UNDEFINED;
    int cmp, a_len, b_len;
    uint32_t *a_buf, *b_buf;

    a = JS_ToStringCheckObject(ctx, this_val);
    if (JS_IsException(a))
        return JS_EXCEPTION;
    b = JS_ToString(ctx, argv[0]);
    if (JS_IsException(b)) {
        
        return JS_EXCEPTION;
    }
    a_len = js_string_normalize1(ctx, &a_buf, a, UNICODE_NFC);
    
    if (a_len < 0) {
        
        return JS_EXCEPTION;
    }

    b_len = js_string_normalize1(ctx, &b_buf, b, UNICODE_NFC);
    
    if (b_len < 0) {
        unicode_libc_realloc(NULL, a_buf, 0);
        return JS_EXCEPTION;
    }
    cmp = js_UTF32_compare(a_buf, a_len, b_buf, b_len);
    unicode_libc_realloc(NULL, a_buf, 0);
    unicode_libc_realloc(NULL, b_buf, 0);
    return JS_NewInt32(ctx, cmp);
}
#else /* CONFIG_ALL_UNICODE */
static GCValue js_string_localeCompare(JSContextHandle ctx, GCValue this_val,
                                       int argc, GCValue *argv)
{
    GCValue a, b;
    int cmp;

    a = JS_ToStringCheckObject(ctx, this_val);
    if (JS_IsException(a))
        return JS_EXCEPTION;
    b = JS_ToString(ctx, argv[0]);
    if (JS_IsException(b)) {
        
        return JS_EXCEPTION;
    }
    cmp = js_string_compare(ctx, JS_VALUE_GET_STRING(a), JS_VALUE_GET_STRING(b));
    
    
    return JS_NewInt32(ctx, cmp);
}
#endif /* !CONFIG_ALL_UNICODE */

/* also used for String.prototype.valueOf */
static GCValue js_string_toString(JSContextHandle ctx, GCValue this_val,
                                  int argc, GCValue *argv)
{
    return js_thisStringValue(ctx, this_val);
}

/* String Iterator */

static GCValue js_string_iterator_next(JSContextHandle ctx, GCValue this_val,
                                       int argc, GCValue *argv,
                                       BOOL *pdone, int magic)
{
    JSArrayIteratorData *it;
    uint32_t idx, c, start;
    JSStringHandle p = GC_HANDLE_NULL;

    GCHandle it_handle = JS_GetOpaqueHandle2(ctx, this_val, JS_CLASS_STRING_ITERATOR);
    if (it_handle == GC_HANDLE_NULL) {
        *pdone = FALSE;
        return JS_EXCEPTION;
    }
    it = (JSArrayIteratorData *)gc_deref(it_handle);
    if (JS_IsUndefined(it->obj))
        goto done;
    p = JS_VALUE_GET_STRING(it->obj);
    idx = it->idx;
    if (idx >= SAFE_GET_OR(p, JSStringHandle, len, 0)) {
        
        it->obj = JS_UNDEFINED;
    done:
        *pdone = TRUE;
        return JS_UNDEFINED;
    }

    start = idx;
    c = string_getc(p, (int *)&idx);
    it->idx = idx;
    *pdone = FALSE;
    if (c <= 0xffff) {
        return js_new_string_char(ctx, c);
    } else {
        return js_new_string16_len(ctx, SAFE_GET_OR(p, JSStringHandle, u.str16, NULL) + start, 2);
    }
}

/* ES6 Annex B 2.3.2 etc. */
enum {
    magic_string_anchor,
    magic_string_big,
    magic_string_blink,
    magic_string_bold,
    magic_string_fixed,
    magic_string_fontcolor,
    magic_string_fontsize,
    magic_string_italics,
    magic_string_link,
    magic_string_small,
    magic_string_strike,
    magic_string_sub,
    magic_string_sup,
};

static GCValue js_string_CreateHTML(JSContextHandle ctx, GCValue this_val,
                                    int argc, GCValue *argv, int magic)
{
    GCValue str = GC_UNDEFINED;
    JSStringHandle p = GC_HANDLE_NULL;
    StringBuffer b_s, *b = &b_s;
    static struct { const char *tag, *attr; } const defs[] = {
        { "a", "name" }, { "big", NULL }, { "blink", NULL }, { "b", NULL },
        { "tt", NULL }, { "font", "color" }, { "font", "size" }, { "i", NULL },
        { "a", "href" }, { "small", NULL }, { "strike", NULL },
        { "sub", NULL }, { "sup", NULL },
    };

    str = JS_ToStringCheckObject(ctx, this_val);
    if (JS_IsException(str))
        return JS_EXCEPTION;
    string_buffer_init(ctx, b, 7);
    string_buffer_putc8(b, '<');
    string_buffer_puts8(b, defs[magic].tag);
    if (defs[magic].attr) {
        // r += " " + attr + "=\"" + value + "\"";
        GCValue value = GC_UNDEFINED;
        int i;

        string_buffer_putc8(b, ' ');
        string_buffer_puts8(b, defs[magic].attr);
        string_buffer_puts8(b, "=\"");
        value = JS_ToStringCheckObject(ctx, argv[0]);
        if (JS_IsException(value)) {
            
            string_buffer_free(b);
            return JS_EXCEPTION;
        }
        p = JS_VALUE_GET_STRING(value);
        for (i = 0; i < SAFE_GET_OR(p, JSStringHandle, len, 0); i++) {
            int c = string_get(p, i);
            if (c == '"') {
                string_buffer_puts8(b, "&quot;");
            } else {
                string_buffer_putc16(b, c);
            }
        }
        
        string_buffer_putc8(b, '\"');
    }
    // return r + ">" + str + "</" + tag + ">";
    string_buffer_putc8(b, '>');
    string_buffer_concat_value_free(b, str);
    string_buffer_puts8(b, "</");
    string_buffer_puts8(b, defs[magic].tag);
    string_buffer_putc8(b, '>');
    return string_buffer_end(b);
}

