void JS_AddIntrinsicRegExpCompiler(JSContextHandle ctx)
{
    SAFE_SET(ctx, JSContextHandle, compile_regexp, js_compile_regexp);
}

int JS_AddIntrinsicRegExp(JSContextHandle ctx)
{
    GCValue obj = GC_UNDEFINED;
    
    JS_AddIntrinsicRegExpCompiler(ctx);

    obj = JS_NewCConstructor(ctx, JS_CLASS_REGEXP, "RegExp",
                                    js_regexp_constructor, 2, JS_CFUNC_constructor_or_func, 0,
                                    JS_UNDEFINED,
                                    js_regexp_funcs, countof(js_regexp_funcs),
                                    js_regexp_proto_funcs, countof(js_regexp_proto_funcs),
                                    0);
    if (JS_IsException(obj))
        return -1;
    SAFE_SET_VALUE(ctx, JSContextHandle, regexp_ctor, obj);
    
    GC_SET(ctx_class_proto[JS_CLASS_REGEXP_STRING_ITERATOR], JS_NewObjectProtoList(ctx, ctx_class_proto[JS_CLASS_ITERATOR],
                              js_regexp_string_iterator_proto_funcs,
                              countof(js_regexp_string_iterator_proto_funcs)));
    if (JS_IsException(ctx_class_proto[JS_CLASS_REGEXP_STRING_ITERATOR]))
        return -1;

    {
        JSShapeHandle sh = js_new_shape2(ctx, get_proto_obj(ctx_class_proto[JS_CLASS_REGEXP]),
                                    JS_PROP_INITIAL_HASH_SIZE, 1);
        if (!SAFE_VALID(sh))
            return -1;
        SAFE_SET_HANDLE(ctx, JSContextHandle, regexp_shape_handle, SAFE_GET_OR(sh, JSShapeHandle, handle, GC_HANDLE_NULL));
    }
    if (add_shape_property(ctx, &SAFE_REF(ctx, JSContextHandle, regexp_shape_handle), (JSObjectHandle)(GC_HANDLE_NULL),
                           JS_ATOM_lastIndex, JS_PROP_WRITABLE))
        return -1;

    {
        JSShapeHandle sh = js_new_shape2(ctx, get_proto_obj(ctx_class_proto[JS_CLASS_ARRAY]),
                                    JS_PROP_INITIAL_HASH_SIZE, 4);
        if (!SAFE_VALID(sh))
            return -1;
        SAFE_SET_HANDLE(ctx, JSContextHandle, regexp_result_shape_handle, SAFE_GET_OR(sh, JSShapeHandle, handle, GC_HANDLE_NULL));
    }
    if (add_shape_property(ctx, &SAFE_REF(ctx, JSContextHandle, regexp_result_shape_handle), (JSObjectHandle)(GC_HANDLE_NULL),
                           JS_ATOM_length, JS_PROP_WRITABLE | JS_PROP_LENGTH))
        return -1;
    if (add_shape_property(ctx, &SAFE_REF(ctx, JSContextHandle, regexp_result_shape_handle), (JSObjectHandle)(GC_HANDLE_NULL),
                           JS_ATOM_index, JS_PROP_C_W_E))
        return -1;
    if (add_shape_property(ctx, &SAFE_REF(ctx, JSContextHandle, regexp_result_shape_handle), (JSObjectHandle)(GC_HANDLE_NULL),
                           JS_ATOM_input, JS_PROP_C_W_E))
        return -1;
    if (add_shape_property(ctx, &SAFE_REF(ctx, JSContextHandle, regexp_result_shape_handle), (JSObjectHandle)(GC_HANDLE_NULL),
                           JS_ATOM_groups, JS_PROP_C_W_E))
        return -1;

    return 0;
}

/* JSON */

static int json_parse_expect(JSParseState *s, int tok)
{
    if (s->token.val != tok) {
        /* XXX: dump token correctly in all cases */
        return js_parse_error(s, "expecting '%c'", tok);
    }
    return json_next_token(s);
}

static GCValue json_parse_value(JSParseState *s)
{
    JSContextHandle ctx = s->ctx;
    GCValue val = JS_NULL;
    int ret;

    switch(s->token.val) {
    case '{':
        {
            GCValue prop_val = GC_UNDEFINED;
            JSAtom prop_name;

            if (json_next_token(s))
                goto fail;
            val = JS_NewObject(ctx);
            if (JS_IsException(val))
                goto fail;
            if (s->token.val != '}') {
                for(;;) {
                    if (s->token.val == TOK_STRING) {
                        prop_name = JS_ValueToAtom(ctx, s->token.u.str.str);
                        if (prop_name == JS_ATOM_NULL)
                            goto fail;
                    } else if (s->ext_json && s->token.val == TOK_IDENT) {
                        prop_name = JS_DupAtom(ctx, s->token.u.ident.atom);
                    } else {
                        js_parse_error(s, "expecting property name");
                        goto fail;
                    }
                    if (json_next_token(s))
                        goto fail1;
                    if (json_parse_expect(s, ':'))
                        goto fail1;
                    prop_val = json_parse_value(s);
                    if (JS_IsException(prop_val)) {
                    fail1:
                        JS_FreeAtom(ctx, prop_name);
                        goto fail;
                    }
                    ret = JS_DefinePropertyValue(ctx, val, prop_name,
                                                 prop_val, JS_PROP_C_W_E);
                    JS_FreeAtom(ctx, prop_name);
                    if (ret < 0)
                        goto fail;

                    if (s->token.val != ',')
                        break;
                    if (json_next_token(s))
                        goto fail;
                    if (s->ext_json && s->token.val == '}')
                        break;
                }
            }
            if (json_parse_expect(s, '}'))
                goto fail;
        }
        break;
    case '[':
        {
            GCValue el = GC_UNDEFINED;
            uint32_t idx;

            if (json_next_token(s))
                goto fail;
            val = JS_NewArray(ctx);
            if (JS_IsException(val))
                goto fail;
            if (s->token.val != ']') {
                idx = 0;
                for(;;) {
                    el = json_parse_value(s);
                    if (JS_IsException(el))
                        goto fail;
                    ret = JS_DefinePropertyValueUint32(ctx, val, idx, el, JS_PROP_C_W_E);
                    if (ret < 0)
                        goto fail;
                    if (s->token.val != ',')
                        break;
                    if (json_next_token(s))
                        goto fail;
                    idx++;
                    if (s->ext_json && s->token.val == ']')
                        break;
                }
            }
            if (json_parse_expect(s, ']'))
                goto fail;
        }
        break;
    case TOK_STRING:
        val = s->token.u.str.str;
        if (json_next_token(s))
            goto fail;
        break;
    case TOK_NUMBER:
        val = s->token.u.num.val;
        if (json_next_token(s))
            goto fail;
        break;
    case TOK_IDENT:
        if (s->token.u.ident.atom == JS_ATOM_false ||
            s->token.u.ident.atom == JS_ATOM_true) {
            val = JS_NewBool(ctx, s->token.u.ident.atom == JS_ATOM_true);
        } else if (s->token.u.ident.atom == JS_ATOM_null) {
            val = JS_NULL;
        } else if (s->token.u.ident.atom == JS_ATOM_NaN && s->ext_json) {
            /* Note: json5 identifier handling is ambiguous e.g. is 
               '{ NaN: 1 }' a valid JSON5 production ? */ 
            val = JS_NewFloat64(s->ctx, NAN);
        } else if (s->token.u.ident.atom == JS_ATOM_Infinity && s->ext_json) {
            val = JS_NewFloat64(s->ctx, INFINITY);
        } else {
            goto def_token;
        }
        if (json_next_token(s))
            goto fail;
        break;
    default:
    def_token:
        if (s->token.val == TOK_EOF) {
            js_parse_error(s, "Unexpected end of JSON input");
        } else {
            js_parse_error(s, "unexpected token: '%.*s'",
                           (int)(s->buf_ptr - s->token.ptr), s->token.ptr);
        }
        goto fail;
    }
    return val;
 fail:
    
    return JS_EXCEPTION;
}

GCValue JS_ParseJSON2(JSContextHandle ctx, const char *buf, size_t buf_len,
                      const char *filename, int flags)
{
    JSParseState s1 = { .token = { .u.str.str = GC_UNDEFINED_INIT } }, *s = &s1;
    GCValue val = JS_UNDEFINED;

    /* JSON parsing doesn't need lazy function parsing (no functions in JSON) */
    js_parse_init(ctx, s, buf, buf_len, filename, JS_EVAL_FLAG_NO_LAZY);
    s->ext_json = ((flags & JS_PARSE_JSON_EXT) != 0);
    if (json_next_token(s))
        goto fail;
    val = json_parse_value(s);
    if (JS_IsException(val))
        goto fail;
    if (s->token.val != TOK_EOF) {
        if (js_parse_error(s, "unexpected data at the end"))
            goto fail;
    }
    return val;
 fail:
    
    free_token(s, &s->token);
    return JS_EXCEPTION;
}

GCValue JS_ParseJSON(JSContextHandle ctx, const char *buf, size_t buf_len,
                     const char *filename)
{
    return JS_ParseJSON2(ctx, buf, buf_len, filename, 0);
}

static GCValue internalize_json_property(JSContextHandle ctx, GCValue holder,
                                         JSAtom name, GCValue reviver)
{
    GCValue val = GC_UNDEFINED, new_el = GC_UNDEFINED, name_val = GC_UNDEFINED, res = GC_UNDEFINED;
    GCValue args[2] = { [0 ... (2) - 1] = GC_UNDEFINED_INIT };
    int ret, is_array;
    uint32_t i, len = 0;
    JSAtom prop;
    JSPropertyEnum *atoms = NULL;

    if (js_check_stack_overflow(ctx_rt, 0)) {
        return JS_ThrowStackOverflow(ctx);
    }

    val = JS_GetProperty(ctx, holder, name);
    if (JS_IsException(val))
        return val;
    if (JS_IsObject(val)) {
        is_array = JS_IsArray(ctx, val);
        if (is_array < 0)
            goto fail;
        if (is_array) {
            if (js_get_length32(ctx, &len, val))
                goto fail;
        } else {
            ret = JS_GetOwnPropertyNamesInternal(ctx, &atoms, &len, JS_VALUE_GET_OBJ(val), JS_GPN_ENUM_ONLY | JS_GPN_STRING_MASK);
            if (ret < 0)
                goto fail;
        }
        for(i = 0; i < len; i++) {
            if (is_array) {
                prop = JS_NewAtomUInt32(ctx, i);
                if (prop == JS_ATOM_NULL)
                    goto fail;
            } else {
                prop = JS_DupAtom(ctx, atoms[i].atom);
            }
            new_el = internalize_json_property(ctx, val, prop, reviver);
            if (JS_IsException(new_el)) {
                JS_FreeAtom(ctx, prop);
                goto fail;
            }
            if (JS_IsUndefined(new_el)) {
                ret = JS_DeleteProperty(ctx, val, prop, 0);
            } else {
                ret = JS_DefinePropertyValue(ctx, val, prop, new_el, JS_PROP_C_W_E);
            }
            JS_FreeAtom(ctx, prop);
            if (ret < 0)
                goto fail;
        }
    }
    JS_FreePropertyEnum(ctx, atoms, len);
    atoms = NULL;
    name_val = JS_AtomToValue(ctx, name);
    if (JS_IsException(name_val))
        goto fail;
    args[0] = name_val;
    args[1] = val;
    res = JS_Call(ctx, reviver, holder, 2, args);
    
    
    return res;
 fail:
    JS_FreePropertyEnum(ctx, atoms, len);
    
    return JS_EXCEPTION;
}

static GCValue js_json_parse(JSContextHandle ctx, GCValue this_val,
                             int argc, GCValue *argv)
{
    GCValue obj = GC_UNDEFINED, root = GC_UNDEFINED;
    GCValue reviver = GC_UNDEFINED;
    const char *str;
    size_t len;

    str = JS_ToCStringLen(ctx, &len, argv[0]);
    if (!str)
        return JS_EXCEPTION;
    obj = JS_ParseJSON(ctx, str, len, "<input>");
    if (JS_IsException(obj))
        return obj;
    if (argc > 1 && JS_IsFunction(ctx, argv[1])) {
        reviver = argv[1];
        root = JS_NewObject(ctx);
        if (JS_IsException(root)) {
            
            return JS_EXCEPTION;
        }
        if (JS_DefinePropertyValue(ctx, root, JS_ATOM_empty_string, obj,
                                   JS_PROP_C_W_E) < 0) {
            
            return JS_EXCEPTION;
        }
        obj = internalize_json_property(ctx, root, JS_ATOM_empty_string,
                                        reviver);
        
    }
    return obj;
}

typedef struct JSONStringifyContext {
    GCValue replacer_func;
    GCValue stack;
    GCValue property_list;
    GCValue gap;
    GCValue empty;
    StringBuffer *b;
} JSONStringifyContext;
#define JSON_STRINGIFY_CONTEXT_INIT { .replacer_func = GC_UNDEFINED_INIT, .stack = GC_UNDEFINED_INIT, .property_list = GC_UNDEFINED_INIT, .gap = GC_UNDEFINED_INIT, .empty = GC_UNDEFINED_INIT }

static int JS_ToQuotedString(JSContextHandle ctx, StringBuffer *b, GCValue val1)
{
    GCValue val = GC_UNDEFINED;
    JSStringHandle p = GC_HANDLE_NULL;
    int i;
    uint32_t c;
    char buf[16];

    val = JS_ToStringCheckObject(ctx, val1);
    if (JS_IsException(val))
        return -1;
    p = JS_VALUE_GET_STRING(val);

    if (string_buffer_putc8(b, '\"'))
        goto fail;
    for(i = 0; i < SAFE_GET_OR(p, JSStringHandle, len, 0); ) {
        c = string_getc(p, &i);
        switch(c) {
        case '\t':
            c = 't';
            goto quote;
        case '\r':
            c = 'r';
            goto quote;
        case '\n':
            c = 'n';
            goto quote;
        case '\b':
            c = 'b';
            goto quote;
        case '\f':
            c = 'f';
            goto quote;
        case '\"':
        case '\\':
        quote:
            if (string_buffer_putc8(b, '\\'))
                goto fail;
            if (string_buffer_putc8(b, c))
                goto fail;
            break;
        default:
            if (c < 32 || is_surrogate(c)) {
                snprintf(buf, sizeof(buf), "\\u%04x", c);
                if (string_buffer_puts8(b, buf))
                    goto fail;
            } else {
                if (string_buffer_putc(b, c))
                    goto fail;
            }
            break;
        }
    }
    if (string_buffer_putc8(b, '\"'))
        goto fail;
    
    return 0;
 fail:
    
    return -1;
}

static int JS_ToQuotedStringFree(JSContextHandle ctx, StringBuffer *b, GCValue val) {
    int ret = JS_ToQuotedString(ctx, b, val);
    
    return ret;
}

static GCValue js_json_check(JSContextHandle ctx, JSONStringifyContext *jsc,
                             GCValue holder, GCValue val, GCValue key)
{
    GCValue v = GC_UNDEFINED;
    GCValue args[2] = { [0 ... (2) - 1] = GC_UNDEFINED_INIT };

    /* check for object.toJSON method */
    /* ECMA specifies this is done only for Object and BigInt */
    if (JS_IsObject(val) || JS_IsBigInt(val)) {
        GCValue f = JS_GetProperty(ctx, val, JS_ATOM_toJSON);
        if (JS_IsException(f))
            goto exception;
        if (JS_IsFunction(ctx, f)) {
            v = JS_CallFree(ctx, f, val, 1, &key);
            
            val = v;
            if (JS_IsException(val))
                goto exception;
        } else {
            
        }
    }

    if (!JS_IsUndefined(jsc->replacer_func)) {
        args[0] = key;
        args[1] = val;
        v = JS_Call(ctx, jsc->replacer_func, holder, 2, args);
        
        val = v;
        if (JS_IsException(val))
            goto exception;
    }

    switch (JS_VALUE_GET_NORM_TAG(val)) {
    case JS_TAG_OBJECT:
        if (JS_IsFunction(ctx, val))
            break;
    case JS_TAG_STRING:
    case JS_TAG_STRING_ROPE:
    case JS_TAG_INT:
    case JS_TAG_FLOAT64:
    case JS_TAG_BOOL:
    case JS_TAG_NULL:
    case JS_TAG_SHORT_BIG_INT:
    case JS_TAG_BIG_INT:
    case JS_TAG_EXCEPTION:
        return val;
    default:
        break;
    }
    
    return JS_UNDEFINED;

exception:
    
    return JS_EXCEPTION;
}

static int js_json_to_str(JSContextHandle ctx, JSONStringifyContext *jsc,
                          GCValue holder, GCValue val,
                          GCValue indent)
{
    GCValue indent1 = GC_UNDEFINED, sep = GC_UNDEFINED, sep1 = GC_UNDEFINED, tab = GC_UNDEFINED, v = GC_UNDEFINED, prop = GC_UNDEFINED;
    JSObjectHandle p = GC_HANDLE_NULL;
    int64_t i, len;
    int cl, ret;
    BOOL has_content;

    indent1 = JS_UNDEFINED;
    sep = JS_UNDEFINED;
    sep1 = JS_UNDEFINED;
    tab = JS_UNDEFINED;
    prop = JS_UNDEFINED;

    if (js_check_stack_overflow(ctx_rt, 0)) {
        JS_ThrowStackOverflow(ctx);
        goto exception;
    }

    if (JS_IsObject(val)) {
        p = JS_VALUE_GET_OBJ(val);
        cl = SAFE_GET_OR(p, JSObjectHandle, class_id, 0);
        if (cl == JS_CLASS_STRING) {
            val = JS_ToStringFree(ctx, val);
            if (JS_IsException(val))
                goto exception;
            goto concat_primitive;
        } else if (cl == JS_CLASS_NUMBER) {
            val = JS_ToNumberFree(ctx, val);
            if (JS_IsException(val))
                goto exception;
            goto concat_primitive;
        } else if (cl == JS_CLASS_BOOLEAN || cl == JS_CLASS_BIG_INT)
        {
            /* This will thow the same error as for the primitive object */
            set_value(ctx, &val, SAFE_GET_OR(p, JSObjectHandle, u.object_data, GC_UNDEFINED));
            goto concat_primitive;
        }
        v = js_array_includes(ctx, jsc->stack, 1, (GCValue *)&val);
        if (JS_IsException(v))
            goto exception;
        if (JS_ToBoolFree(ctx, v)) {
            JS_ThrowTypeError(ctx, "circular reference");
            goto exception;
        }
        indent1 = JS_ConcatString(ctx, indent, jsc->gap);
        if (JS_IsException(indent1))
            goto exception;
        if (!JS_IsEmptyString(jsc->gap)) {
            sep = JS_ConcatString3(ctx, "\n", indent1, "");
            if (JS_IsException(sep))
                goto exception;
            sep1 = js_new_string8(ctx, " ");
            if (JS_IsException(sep1))
                goto exception;
        } else {
            sep = jsc->empty;
            sep1 = jsc->empty;
        }
        v = js_array_push(ctx, jsc->stack, 1, (GCValue *)&val, 0);
        if (check_exception_free(ctx, v))
            goto exception;
        ret = JS_IsArray(ctx, val);
        if (ret < 0)
            goto exception;
        if (ret) {
            if (js_get_length64(ctx, &len, val))
                goto exception;
            string_buffer_putc8(jsc->b, '[');
            for(i = 0; i < len; i++) {
                if (i > 0)
                    string_buffer_putc8(jsc->b, ',');
                string_buffer_concat_value(jsc->b, sep);
                v = JS_GetPropertyInt64(ctx, val, i);
                if (JS_IsException(v))
                    goto exception;
                /* XXX: could do this string conversion only when needed */
                prop = JS_ToStringFree(ctx, JS_NewInt64(ctx, i));
                if (JS_IsException(prop))
                    goto exception;
                v = js_json_check(ctx, jsc, val, v, prop);
                
                prop = JS_UNDEFINED;
                if (JS_IsException(v))
                    goto exception;
                if (JS_IsUndefined(v))
                    v = JS_NULL;
                if (js_json_to_str(ctx, jsc, val, v, indent1))
                    goto exception;
            }
            if (len > 0 && !JS_IsEmptyString(jsc->gap)) {
                string_buffer_putc8(jsc->b, '\n');
                string_buffer_concat_value(jsc->b, indent);
            }
            string_buffer_putc8(jsc->b, ']');
        } else {
            if (!JS_IsUndefined(jsc->property_list))
                tab = jsc->property_list;
            else
                tab = js_object_keys(ctx, JS_UNDEFINED, 1, (GCValue *)&val, JS_ITERATOR_KIND_KEY);
            if (JS_IsException(tab))
                goto exception;
            if (js_get_length64(ctx, &len, tab))
                goto exception;
            string_buffer_putc8(jsc->b, '{');
            has_content = FALSE;
            for(i = 0; i < len; i++) {
                
                prop = JS_GetPropertyInt64(ctx, tab, i);
                if (JS_IsException(prop))
                    goto exception;
                v = JS_GetPropertyValue(ctx, val, prop);
                if (JS_IsException(v))
                    goto exception;
                v = js_json_check(ctx, jsc, val, v, prop);
                if (JS_IsException(v))
                    goto exception;
                if (!JS_IsUndefined(v)) {
                    if (has_content)
                        string_buffer_putc8(jsc->b, ',');
                    string_buffer_concat_value(jsc->b, sep);
                    if (JS_ToQuotedString(ctx, jsc->b, prop)) {
                        
                        goto exception;
                    }
                    string_buffer_putc8(jsc->b, ':');
                    string_buffer_concat_value(jsc->b, sep1);
                    if (js_json_to_str(ctx, jsc, val, v, indent1))
                        goto exception;
                    has_content = TRUE;
                }
            }
            if (has_content && !JS_IsEmptyString(jsc->gap)) {
                string_buffer_putc8(jsc->b, '\n');
                string_buffer_concat_value(jsc->b, indent);
            }
            string_buffer_putc8(jsc->b, '}');
        }
        if (check_exception_free(ctx, js_array_pop(ctx, jsc->stack, 0, NULL, 0)))
            goto exception;
        
        
        
        
        
        
        return 0;
    }
 concat_primitive:
    switch (JS_VALUE_GET_NORM_TAG(val)) {
    case JS_TAG_STRING:
    case JS_TAG_STRING_ROPE:
        return JS_ToQuotedStringFree(ctx, jsc->b, val);
    case JS_TAG_FLOAT64:
        if (!isfinite(JS_VALUE_GET_FLOAT64(val))) {
            val = JS_NULL;
        }
        goto concat_value;
    case JS_TAG_INT:
    case JS_TAG_BOOL:
    case JS_TAG_NULL:
    concat_value:
        return string_buffer_concat_value_free(jsc->b, val);
    case JS_TAG_SHORT_BIG_INT:
    case JS_TAG_BIG_INT:
        /* reject big numbers: use toJSON method to override */
        JS_ThrowTypeError(ctx, "Do not know how to serialize a BigInt");
        goto exception;
    default:
        
        return 0;
    }

exception:
    
    
    
    
    
    
    return -1;
}

GCValue JS_JSONStringify(JSContextHandle ctx, GCValue obj,
                         GCValue replacer, GCValue space0)
{
    StringBuffer b_s;
    JSONStringifyContext jsc_s = JSON_STRINGIFY_CONTEXT_INIT, *jsc = &jsc_s;
    GCValue val = GC_UNDEFINED, v = GC_UNDEFINED, space = GC_UNDEFINED, ret = GC_UNDEFINED, wrapper = GC_UNDEFINED;
    int res;
    int64_t i, j, n;

    jsc->replacer_func = JS_UNDEFINED;
    jsc->stack = JS_UNDEFINED;
    jsc->property_list = JS_UNDEFINED;
    jsc->gap = JS_UNDEFINED;
    jsc->b = &b_s;
    GC_SET(jsc->empty, JS_AtomToString(ctx, JS_ATOM_empty_string));
    ret = JS_UNDEFINED;
    wrapper = JS_UNDEFINED;

    string_buffer_init(ctx, jsc->b, 0);
    GC_SET(jsc->stack, JS_NewArray(ctx));
    if (JS_IsException(jsc->stack))
        goto exception;
    if (JS_IsFunction(ctx, replacer)) {
        GC_SET(jsc->replacer_func, replacer);
    } else {
        res = JS_IsArray(ctx, replacer);
        if (res < 0)
            goto exception;
        if (res) {
            /* XXX: enumeration is not fully correct */
            jsc->property_list = JS_NewArray(ctx);  /* gc-no-dirty: stringify context on the C stack */
            if (JS_IsException(jsc->property_list))
                goto exception;
            if (js_get_length64(ctx, &n, replacer))
                goto exception;
            for (i = j = 0; i < n; i++) {
                GCValue present = GC_UNDEFINED;
                v = JS_GetPropertyInt64(ctx, replacer, i);
                if (JS_IsException(v))
                    goto exception;
                if (JS_IsObject(v)) {
                    JSObjectHandle p = JS_VALUE_GET_OBJ(v);
                    if (SAFE_GET_OR(p, JSObjectHandle, class_id, 0) == JS_CLASS_STRING ||
                        SAFE_GET_OR(p, JSObjectHandle, class_id, 0) == JS_CLASS_NUMBER) {
                        v = JS_ToStringFree(ctx, v);
                        if (JS_IsException(v))
                            goto exception;
                    } else {
                        
                        continue;
                    }
                } else if (JS_IsNumber(v)) {
                    v = JS_ToStringFree(ctx, v);
                    if (JS_IsException(v))
                        goto exception;
                } else if (!JS_IsString(v)) {
                    
                    continue;
                }
                present = js_array_includes(ctx, jsc->property_list,
                                            1, (GCValue *)&v);
                if (JS_IsException(present)) {
                    
                    goto exception;
                }
                if (!JS_ToBoolFree(ctx, present)) {
                    JS_SetPropertyInt64(ctx, jsc->property_list, j++, v);
                } else {
                    
                }
            }
        }
    }
    space = space0;
    if (JS_IsObject(space)) {
        JSObjectHandle p = JS_VALUE_GET_OBJ(space);
        if (SAFE_GET_OR(p, JSObjectHandle, class_id, 0) == JS_CLASS_NUMBER) {
            space = JS_ToNumberFree(ctx, space);
        } else if (SAFE_GET_OR(p, JSObjectHandle, class_id, 0) == JS_CLASS_STRING) {
            space = JS_ToStringFree(ctx, space);
        }
        if (JS_IsException(space)) {
            
            goto exception;
        }
    }
    if (JS_IsNumber(space)) {
        int n;
        if (JS_ToInt32Clamp(ctx, &n, space, 0, 10, 0))
            goto exception;
        GC_SET(jsc->gap, js_new_string8_len(ctx, "          ", n));
    } else if (JS_IsString(space)) {
        JSStringHandle p = JS_VALUE_GET_STRING(space);
        GC_SET(jsc->gap, js_sub_string(ctx, p, 0, min_int(SAFE_GET_OR(p, JSStringHandle, len, 0), 10)));
    } else {
        GC_SET(jsc->gap, jsc->empty);
    }
    
    if (JS_IsException(jsc->gap))
        goto exception;
    wrapper = JS_NewObject(ctx);
    if (JS_IsException(wrapper))
        goto exception;
    if (JS_DefinePropertyValue(ctx, wrapper, JS_ATOM_empty_string,
                               obj, JS_PROP_C_W_E) < 0)
        goto exception;
    val = obj;

    val = js_json_check(ctx, jsc, wrapper, val, jsc->empty);
    if (JS_IsException(val))
        goto exception;
    if (JS_IsUndefined(val)) {
        ret = JS_UNDEFINED;
        goto done1;
    }
    if (js_json_to_str(ctx, jsc, wrapper, val, jsc->empty))
        goto exception;

    ret = string_buffer_end(jsc->b);
    goto done;

exception:
    ret = JS_EXCEPTION;
done1:
    string_buffer_free(jsc->b);
done:
    
    
    
    
    
    return ret;
}

static GCValue js_json_stringify(JSContextHandle ctx, GCValue this_val,
                                 int argc, GCValue *argv)
{
    // stringify(val, replacer, space)
    return JS_JSONStringify(ctx, argv[0], argv[1], argv[2]);
}

