static GCValue js_symbol_for(JSContextHandle ctx, GCValue this_val,
                             int argc, GCValue *argv)
{
    GCValue str = GC_UNDEFINED;

    str = JS_ToString(ctx, argv[0]);
    if (JS_IsException(str))
        return JS_EXCEPTION;
    return JS_NewSymbol(ctx, JS_VALUE_GET_STRING(str), JS_ATOM_TYPE_GLOBAL_SYMBOL);
}

static GCValue js_symbol_keyFor(JSContextHandle ctx, GCValue this_val,
                                int argc, GCValue *argv)
{
    JSStringHandle p = GC_HANDLE_NULL;

    if (!JS_IsSymbol(argv[0]))
        return JS_ThrowTypeError(ctx, "not a symbol");
    p = JS_VALUE_GET_STRING(argv[0]);
    if (SAFE_GET_OR(p, JSStringHandle, atom_type, 0) != JS_ATOM_TYPE_GLOBAL_SYMBOL)
        return JS_UNDEFINED;
    return GC_MKHANDLE(JS_TAG_STRING, SAFE_HANDLE(p));
}

