static GCValue js_set_difference(JSContextHandle ctx, GCValue this_val,
                                 int argc, GCValue *argv)
{
    GCValue newset = GC_UNDEFINED, item = GC_UNDEFINED, iter = GC_UNDEFINED, keys = GC_UNDEFINED, has = GC_UNDEFINED, next = GC_UNDEFINED, rv = GC_UNDEFINED;
    JSMapStateHandle s = GC_HANDLE_NULL;
    int64_t size;
    int done;
    int ok;

    iter = JS_UNDEFINED;
    next = JS_UNDEFINED;
    newset = JS_UNDEFINED;
    GCHandle s_handle6 = JS_GetOpaqueHandle2(ctx, this_val, JS_CLASS_SET);
    s = (JSMapStateHandle)(s_handle6);
    if (!SAFE_VALID(s))
        return JS_EXCEPTION;
    if (get_set_record(ctx, argv[0], &size, &has, &keys) < 0)
        return JS_EXCEPTION;

    newset = js_copy_set(ctx, this_val);
    if (JS_IsException(newset))
        return JS_EXCEPTION;
    {
        GCHandle t_handle3 = JS_GetOpaqueHandle(newset, JS_CLASS_SET);
        JSMapStateHandle t = t_handle3;
    
        if (SAFE_GET_OR(s, JSMapStateHandle, record_count, 0) <= size) {
            iter = js_create_map_iterator(ctx, newset, 0, NULL, MAGIC_SET);
            if (JS_IsException(iter))
                return JS_EXCEPTION;
            for (;;) {
                item = js_map_iterator_next(ctx, iter, 0, NULL, &done, MAGIC_SET);
                if (JS_IsException(item))
                    return JS_EXCEPTION;
                if (done) // item is JS_UNDEFINED
                    break;
                rv = JS_Call(ctx, has, argv[0], 1, (GCValue *)&item);
                ok = JS_ToBoolFree(ctx, rv); // returns -1 if rv is JS_EXCEPTION
                if (ok < 0)
                    return JS_EXCEPTION;
                if (ok)
                    map_delete_record_handle(ctx, t, item);
            }
        } else {
            iter = JS_Call(ctx, keys, argv[0], 0, NULL);
            if (JS_IsException(iter))
                return JS_EXCEPTION;
            next = JS_GetProperty(ctx, iter, JS_ATOM_next);
            if (JS_IsException(next))
                return JS_EXCEPTION;
            for (;;) {
                item = JS_IteratorNext(ctx, iter, next, 0, NULL, &done);
                if (JS_IsException(item))
                    return JS_EXCEPTION;
                if (done) // item is JS_UNDEFINED
                    break;
                map_delete_record_handle(ctx, t, item);
            }
        }
    }
    return newset;
}

static GCValue js_set_symmetricDifference(JSContextHandle ctx, GCValue this_val,
                                          int argc, GCValue *argv)
{
    GCValue newset = GC_UNDEFINED, item = GC_UNDEFINED, iter = GC_UNDEFINED, next = GC_UNDEFINED, has = GC_UNDEFINED, keys = GC_UNDEFINED;
    JSMapStateHandle s = GC_HANDLE_NULL;
    JSMapRecord *mr;
    int64_t size;
    int done;
    BOOL present;

    GCHandle s_handle7 = JS_GetOpaqueHandle2(ctx, this_val, JS_CLASS_SET);
    s = (JSMapStateHandle)(s_handle7);
    if (!SAFE_VALID(s))
        return JS_EXCEPTION;
    if (get_set_record(ctx, argv[0], &size, &has, &keys) < 0)
        return JS_EXCEPTION;
    

    next = JS_UNDEFINED;
    newset = JS_UNDEFINED;
    iter = JS_Call(ctx, keys, argv[0], 0, NULL);
    if (JS_IsException(iter))
        return JS_EXCEPTION;
    next = JS_GetProperty(ctx, iter, JS_ATOM_next);
    if (JS_IsException(next))
        return JS_EXCEPTION;
    newset = js_copy_set(ctx, this_val);
    if (JS_IsException(newset))
        return JS_EXCEPTION;
    {
        GCHandle t_handle4 = JS_GetOpaqueHandle(newset, JS_CLASS_SET);
        JSMapStateHandle t = t_handle4;
        for (;;) {
            item = JS_IteratorNext(ctx, iter, next, 0, NULL, &done);
            if (JS_IsException(item))
                return JS_EXCEPTION;
            if (done) // item is JS_UNDEFINED
                break;
            // note the subtlety here: due to mutating iterators, it's
            // possible for keys to disappear during iteration; test262
            // still expects us to maintain insertion order though, so
            // we first check |this|, then |new|; |new| is a copy of |this|
            // - if item exists in |this|, delete (if it exists) from |new|
            // - if item misses in |this| and |new|, add to |new|
            // - if item exists in |new| but misses in |this|, *don't* add it,
            //   mutating iterator erased it
            item = map_normalize_key(ctx, item);
            present = (map_find_record_handle(ctx, s, item) != GC_HANDLE_NULL);
            GCHandle mr_handle = map_find_record_handle(ctx, t, item);
            if (present) {
                map_delete_record_handle(ctx, t, item);
            } else if (mr_handle != GC_HANDLE_NULL) {
                // do nothing
            } else {
                if (set_add_record_handle(ctx, t, item) == GC_HANDLE_NULL)
                    return JS_EXCEPTION;
            }
        }
    }
    return newset;
}

static GCValue js_set_union(JSContextHandle ctx, GCValue this_val,
                            int argc, GCValue *argv)
{
    GCValue newset = GC_UNDEFINED, item = GC_UNDEFINED, iter = GC_UNDEFINED, next = GC_UNDEFINED, has = GC_UNDEFINED, keys = GC_UNDEFINED, rv = GC_UNDEFINED;
    JSMapStateHandle s = GC_HANDLE_NULL;
    int64_t size;
    int done;

    GCHandle s_handle8 = JS_GetOpaqueHandle2(ctx, this_val, JS_CLASS_SET);
    s = (JSMapStateHandle)(s_handle8);
    if (!SAFE_VALID(s))
        return JS_EXCEPTION;
    if (get_set_record(ctx, argv[0], &size, &has, &keys) < 0)
        return JS_EXCEPTION;
    

    next = JS_UNDEFINED;
    newset = JS_UNDEFINED;
    iter = JS_Call(ctx, keys, argv[0], 0, NULL);
    if (JS_IsException(iter))
        goto exception;
    next = JS_GetProperty(ctx, iter, JS_ATOM_next);
    if (JS_IsException(next))
        goto exception;

    newset = js_copy_set(ctx, this_val);
    if (JS_IsException(newset))
        goto exception;

    for (;;) {
        item = JS_IteratorNext(ctx, iter, next, 0, NULL, &done);
        if (JS_IsException(item))
            goto exception;
        if (done) // item is JS_UNDEFINED
            break;
        rv = js_map_set(ctx, newset, 1, (GCValue *)&item, MAGIC_SET);
        
        if (JS_IsException(rv))
            goto exception;
        
    }
    goto fini;
exception:
    
    newset = JS_EXCEPTION;
fini:
    
    
    
    return newset;
}

