/* Job queue access - returns GCHandle to job entry */
uint32_t JSRuntime_job_queue_count(JSRuntimeHandle rt) {
    JobQueue *job_queue = js_job_queue_ptr(rt);
    if (!job_queue) return 0;
    uint64_t count = 0;
    JobBuffer *b = (JobBuffer *)atomic_load_ptr((void *volatile *)&job_queue->head_block);
    while (b) {
        uint64_t head = atomic_load_u64(&b->head);
        uint64_t tail = atomic_load_u64(&b->tail);
        for (uint64_t idx = head; idx < tail; idx++) {
            GCHandle job_handle = atomic_load_u32((volatile uint32_t *)&b->jobs[idx]);
            if (gc_handle_array_entry_is_valid(job_handle) && !gc_object_is_dead(job_handle))
                count++;
        }
        b = (JobBuffer *)atomic_load_ptr((void *volatile *)&b->next);
    }
    return (uint32_t)count;
}

uint32_t JSRuntime_job_queue_get_handle(JSRuntimeHandle rt, int index) {
    JobQueue *job_queue = js_job_queue_ptr(rt);
    if (!job_queue || index < 0) return GC_HANDLE_NULL;

    JobBuffer *b = (JobBuffer *)atomic_load_ptr((void *volatile *)&job_queue->head_block);
    while (b) {
        uint64_t head = atomic_load_u64(&b->head);
        uint64_t tail = atomic_load_u64(&b->tail);
        for (uint64_t idx = head; idx < tail; idx++) {
            GCHandle job_handle = atomic_load_u32((volatile uint32_t *)&b->jobs[idx]);
            if (!gc_handle_array_entry_is_valid(job_handle)) continue;
            if (gc_object_is_dead(job_handle)) continue;
            if (index == 0) return job_handle;
            index--;
        }
        b = (JobBuffer *)atomic_load_ptr((void *volatile *)&b->next);
    }

    return GC_HANDLE_NULL;
}

/* Access job entry fields directly via handle */
uint32_t JSJobEntry_get_realm_handle(uint32_t job_handle) {
    if (job_handle == GC_HANDLE_NULL) return GC_HANDLE_NULL;
    JSJobEntryHandle jh = job_handle;
    if (!SAFE_VALID(jh)) return GC_HANDLE_NULL;
    return SAFE_GET_OR(jh, JSJobEntryHandle, realm_handle, GC_HANDLE_NULL);
}

int JSJobEntry_get_argc(uint32_t job_handle) {
    if (job_handle == GC_HANDLE_NULL) return 0;
    JSJobEntryHandle jh = job_handle;
    if (!SAFE_VALID(jh)) return 0;
    return SAFE_GET_OR(jh, JSJobEntryHandle, argc, 0);
}

GCValue JSJobEntry_get_argv(uint32_t job_handle, int index) {
    GCValue result = GC_UNDEFINED;
    if (job_handle == GC_HANDLE_NULL) return result;
    JSJobEntryHandle jh = job_handle;
    if (!SAFE_VALID(jh)) return result;
    if (index >= 0 && index < SAFE_GET_OR(jh, JSJobEntryHandle, argc, 0)) {
        return js_job_argv_at(jh, index);
    }
    return result;
}

