/* Context iteration callback type */
typedef void (*ContextIteratorFunc)(uint32_t ctx_handle, void *user_data);

typedef struct ContextIteratorData {
    ContextIteratorFunc func;
    void *user_data;
    JSRuntimeHandle rt;
} ContextIteratorData;

static void js_runtime_context_iterator_callback(GCHandle handle, void *user_data) {
    ContextIteratorData *cb = (ContextIteratorData *)user_data;
    cb->func(handle, cb->user_data);
}

void JSRuntime_for_each_context(JSRuntimeHandle rt, ContextIteratorFunc func, void *user_data) {
    ContextIteratorData cb = {func, user_data, rt};
    gc_for_each_object_of_type(JS_GC_OBJ_TYPE_JS_CONTEXT, js_runtime_context_iterator_callback, &cb);
}

/* GCValue conversion helper for JS_MarkValue bridge - not needed since we use GCValue directly */
/* extern "C" void JS_MarkValue_bridge(JSRuntimeHandle rt, GCValue *val, JS_MarkFunc *mark_func); */

/* ============================================================================
 * Lock-free property-array allocator API
 * ============================================================================
 * These functions provide the versioning + atomic-slot-CAS machinery described
 * in PARALLEL_CSS_APPLICATION.md.  They are safe for concurrent worker writes
 * to the property slots of a single object, provided the object is pre-sized
 * so that no resize occurs while workers are active.
 */

static inline JSProperty *js_object_get_prop_slot(JSObjectHandle p, uint32_t prop_idx)
{
    return js_prop_array_at(js_obj_props(p), prop_idx);
}

/* Atomic access to one value slot: 16 bytes through cmpxchg16b, or one
 * 8-byte word with 8-byte values (QJS_VALUE8). */
#ifdef QJS_VALUE8
static inline GCValue gcv_atomic_load(GCValue *p)
{
    GCValue v;
    GCV_BITS(v) = atomic_load_explicit((_Atomic uint64_t *)p, memory_order_acquire);
    return v;
}
static inline void gcv_atomic_store(GCValue *p, GCValue v)
{
    atomic_store_explicit((_Atomic uint64_t *)p, GCV_BITS(v), memory_order_release);
}
/* *expected gets the slot's value when they differ. */
static inline bool gcv_atomic_cas(GCValue *p, GCValue *expected, GCValue desired)
{
    return atomic_compare_exchange_strong((_Atomic uint64_t *)p, &GCV_BITS(*expected), GCV_BITS(desired));
}
#else
static inline GCValue gcv_atomic_load(GCValue *p)
{
    uint64_t w[2];
    GCValue v;
    atomic_load_128((volatile uint64_t *)p, &w[0], &w[1]);
    memcpy(&v, w, sizeof(v));
    return v;
}
static inline void gcv_atomic_store(GCValue *p, GCValue v)
{
    uint64_t w[2];
    memcpy(w, &v, sizeof(v));
    atomic_store_128((volatile uint64_t *)p, w[0], w[1]);
}
static inline bool gcv_atomic_cas(GCValue *p, GCValue *expected, GCValue desired)
{
    uint64_t e[2], d[2];
    bool ok;
    memcpy(e, expected, sizeof(e));
    memcpy(d, &desired, sizeof(d));
    ok = atomic_compare_exchange_128((volatile uint64_t *)p, &e[0], &e[1], d[0], d[1]);
    memcpy(expected, e, sizeof(e));
    return ok;
}
#endif

bool js_object_prealloc_properties(JSContextHandle ctx, GCHandle obj_handle, uint32_t min_count)
{
    return js_object_prealloc_properties_impl(ctx, obj_handle, min_count);
}

uint32_t js_object_prop_version_load(GCHandle obj_handle)
{
    return js_obj_prop_version(obj_handle);
}

bool js_object_set_property_value_atomic(JSContextHandle ctx, GCHandle obj_handle,
                                                      uint32_t prop_idx, GCValue val)
{
    JSObjectHandle p = obj_handle;
    if (!SAFE_VALID(p))
        return false;

    for (;;) {
        uint32_t v0 = js_obj_prop_version(p);
        if ((v0 & 1) != 0) {
            /* resize in progress - spin */
            continue;
        }
        JSProperty *slot = js_object_get_prop_slot(p, prop_idx);
        if (!slot)
            return false;

        gcv_atomic_store(&slot->u.value, val);
        gc_dirty_slot(&slot->u.value);

        uint32_t v1 = js_obj_prop_version(p);
        if (v1 == v0) {
            GCHandle target = GC_VALUE_GET_HANDLE(val);
            if (target != GC_HANDLE_NULL)
                gc_write_barrier_for_heap_slot(&slot->u.value, target);
            return true;
        }
        /* Version changed: retry with the (possibly) new array. */
    }
}

bool js_object_cas_property_value_atomic(JSContextHandle ctx, GCHandle obj_handle,
                                                      uint32_t prop_idx, GCValue expected,
                                                      GCValue desired, GCValue *out_actual)
{
    JSObjectHandle p = obj_handle;
    if (!SAFE_VALID(p))
        return false;

    for (;;) {
        uint32_t v0 = js_obj_prop_version(p);
        if ((v0 & 1) != 0) {
            continue;
        }
        JSProperty *slot = js_object_get_prop_slot(p, prop_idx);
        if (!slot)
            return false;

        GCValue actual = expected;
        bool success = gcv_atomic_cas(&slot->u.value, &actual, desired);
        if (out_actual)
            GC_SET(*out_actual, actual);

        uint32_t v1 = js_obj_prop_version(p);
        if (v1 == v0) {
            if (success) {
                GCHandle target = GC_VALUE_GET_HANDLE(desired);
                if (target != GC_HANDLE_NULL)
                    gc_write_barrier_for_heap_slot(&slot->u.value, target);
            }
            return success;
        }
    }
}

GCValue js_object_get_property_value_atomic(JSContextHandle ctx, GCHandle obj_handle,
                                                         uint32_t prop_idx)
{
    JSObjectHandle p = obj_handle;
    GCValue result = GC_UNDEFINED;
    if (!SAFE_VALID(p))
        return result;

    for (;;) {
        uint32_t v0 = js_obj_prop_version(p);
        if ((v0 & 1) != 0)
            continue;
        JSProperty *slot = js_object_get_prop_slot(p, prop_idx);
        if (!slot)
            return result;

        result = gcv_atomic_load(&slot->u.value);

        if (js_obj_prop_version(p) == v0)
            return result;
    }
}

/* Atomic load of a context class-prototype entry.  The context prototype array
   is immutable after init except during rare class registration, so readers
   use an odd/even version check to avoid observing a torn GCValue. */
GCValue js_ctx_class_proto_get(JSContextHandle ctx, JSClassID class_id)
{
    for (;;) {
        uint32_t v0 = js_ctx_class_proto_version(ctx);
        if ((v0 & 1) != 0)
            continue;
        GCValue *tab = ((GCValue*)gc_deref(SAFE_GET_OR(ctx, JSContextHandle, class_proto_handle, GC_HANDLE_NULL)));
        if (!tab || class_id >= (JSClassID)js_rt_class_count(ctx_rt))
            return JS_NULL;
        GCValue val = gcv_atomic_load(&tab[class_id]);
        if (js_ctx_class_proto_version(ctx) == v0)
            return val;
    }
}

/* Atomic store of a context class-prototype entry.  Called during context init
   and when JS_NewClass1 resizes the per-context prototype table. */
void js_ctx_class_proto_set(JSContextHandle ctx, JSClassID class_id, GCValue val)
{
    js_ctx_class_proto_lock_acquire(ctx);
    js_ctx_class_proto_version_fetch_add(ctx, 1); /* odd */
    GCValue *tab = ((GCValue*)gc_deref(SAFE_GET_OR(ctx, JSContextHandle, class_proto_handle, GC_HANDLE_NULL)));
    if (tab && class_id < (JSClassID)js_rt_class_count(ctx_rt)) {
        gcv_atomic_store(&tab[class_id], val);
        gc_dirty_slot(&tab[class_id]);
        GCHandle target = GC_VALUE_GET_HANDLE(val);
        if (target != GC_HANDLE_NULL)
            gc_write_barrier_for_heap_slot(&tab[class_id], target);
    }
    js_ctx_class_proto_version_fetch_add(ctx, 1); /* even */
    js_ctx_class_proto_lock_release(ctx);
}
